// Need router: signals to paths with safe fallback (plain JS)
function routeNeed(q) {
  if (/ignore|system:|disregard/i.test(q)) return "quarantine";
  if (/ORD-[0-9]+|order\s*#?\s*\d+/i.test(q)) return "tools";
  if (/^(hi|hey|thanks|bye)\b/i.test(q.trim())) return "direct";
  if (/delete|close account/i.test(q)) return "escalate";
  return "retrieve"; // default: knowledge path (safe, cited, abstain-capable)
}
// Confidence overlay in production: low-confidence retrieval → escalate (not guess).

// Bounded multi-hop: accumulate, check, cap, de-cycle (plain JS pattern)
async function multiHop(retrieve, answerable, query, budget = { hops: 3 }) {
  const seen = new Set();
  let ctx = [];
  for (let h = 0; h < budget.hops; h++) {
    const batch = (await retrieve(query, ctx)).filter((c) => !seen.has(c.id));
    batch.forEach((c) => seen.add(c.id));
    ctx = ctx.concat(batch);
    if (answerable(ctx, query)) return { ok: true, ctx, hops: h + 1 };
  }
  return { ok: false, reason: "hop-budget", ctx }; // escalate with partial context
}
// Visited-set kills cycles; budgets kill hangs; partial context aids escalation.

